{
  "name": "@leo.gimp/opencode-sessions-sidebar",
  "version": "1.0.4",
  "description": "Renders open session tabs as a Sessions block at the bottom of the OpenCode sidebar",
  "license": "MIT",
  "author": {
    "name": "Leogimp",
    "url": "https://github.com/Leogimp"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Leogimp/opencode-sessions-sidebar.git"
  },
  "bugs": {
    "url": "https://github.com/Leogimp/opencode-sessions-sidebar/issues"
  },
  "homepage": "https://github.com/Leogimp/opencode-sessions-sidebar#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "tui-plugin",
    "sessions",
    "sidebar",
    "tabs",
    "solidjs"
  ],
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.10",
    "@opentui/core": "^0.6.3",
    "@opentui/solid": "^0.6.3",
    "solid-js": "^1.9.15"
  },
  "devDependencies": {
    "typescript": "^5.8.2"
  }
}

// Server-side no-op entrypoint. The real functionality lives in ./tui.tsx
// (loaded by the OpenCode TUI via the "./tui" export). This entrypoint exists
// so the server plugin loader can resolve the package cleanly without
// touching TUI-only dependencies. Deliberately import-free: local plugin
// entrypoints are loaded with a minimal module map on the server, so we keep
// this file dependency-free.
export default {
  id: "sessions-sidebar",
  async setup() {
    // No server behavior.
  },
}
